import { EndpointError } from "@smithy/core/dist-es/submodules/endpoints/util-endpoints/types";
import { evaluateConditions } from "@smithy/core/dist-es/submodules/endpoints/util-endpoints/utils/evaluateConditions";
import { evaluateExpression } from "@smithy/core/dist-es/submodules/endpoints/util-endpoints/utils/evaluateExpression";
export const evaluateErrorRule = (errorRule, options) => {
    const { conditions, error } = errorRule;
    const { result, referenceRecord } = evaluateConditions(conditions, options);
    if (!result) {
        return;
    }
    const errorRuleOptions = referenceRecord
        ? {
            ...options,
            referenceRecord: { ...options.referenceRecord, ...referenceRecord },
        }
        : options;
    throw new EndpointError(evaluateExpression(error, "Error", errorRuleOptions));
};
